select x->>'id', x->>'group', x->>'title', (o-1) from jsonb_array_elements($j$[{"id": "hunger", "group": "고객 상태", "title": "지금 얼마나 배고프세요?", "options": [{"value": "출출해요", "label": "조금 출출해요", "emoji": "🙂"}, {"value": "적당해요", "label": "적당해요", "emoji": "😋"}, {"value": "매우 배고파요", "label": "매우 배고파요", "emoji": "🤤"}]}, {"id": "stress", "group": "고객 상태", "title": "오늘 스트레스 지수는 어느 정도예요?", "options": [{"value": "낮음", "label": "낮아요", "emoji": "😊"}, {"value": "보통", "label": "보통이에요", "emoji": "😐"}, {"value": "높음", "label": "높아요", "emoji": "😤"}]}, {"id": "people", "group": "방문 인원", "title": "함께 오신 분은 몇 명인가요?", "options": [{"value": 1, "label": "1명", "emoji": "🧑"}, {"value": 2, "label": "2명", "emoji": "👫"}, {"value": 3, "label": "3명", "emoji": "👨‍👩‍👦"}, {"value": 4, "label": "4명", "emoji": "👨‍👩‍👧‍👦"}, {"value": 5, "label": "5명 이상", "emoji": "🧑‍🤝‍🧑"}]}, {"id": "gender", "group": "방문 인원", "title": "일행의 성별은 어떻게 되나요?", "options": [{"value": "남자만", "label": "남자끼리", "emoji": "👨"}, {"value": "여자만", "label": "여자끼리", "emoji": "👩"}, {"value": "혼성", "label": "남녀 함께", "emoji": "👫"}]}, {"id": "kind", "group": "음식 취향", "title": "어떤 종류가 끌리세요?", "options": [{"value": "fried", "label": "튀김·치킨", "emoji": "🍗"}, {"value": "anju", "label": "안주류", "emoji": "🍢"}, {"value": "soup", "label": "탕·국물", "emoji": "🍲"}, {"value": "seafood", "label": "해산물", "emoji": "🦑"}, {"value": "rice_noodle", "label": "밥·면", "emoji": "🍜"}, {"value": "any", "label": "상관없어요", "emoji": "🍽️"}]}, {"id": "spicy", "group": "음식 취향", "title": "맵기는 어느 정도가 좋으세요?", "options": [{"value": "맵지 않게", "label": "맵지 않게", "emoji": "🥛"}, {"value": "상관없어요", "label": "보통이면 좋아요", "emoji": "🌶️"}, {"value": "매콤하게", "label": "매콤하게!", "emoji": "🔥"}]}, {"id": "intent", "group": "방문 상황", "title": "오늘 방문 목적은 무엇인가요?", "options": [{"value": "모임", "label": "친구·모임", "emoji": "🍻"}, {"value": "회식", "label": "회식", "emoji": "🥂"}, {"value": "데이트", "label": "데이트", "emoji": "💕"}, {"value": "가볍게", "label": "가볍게 한잔", "emoji": "🍺"}, {"value": "스트레스", "label": "스트레스 풀러", "emoji": "💥"}]}, {"id": "budget", "group": "소비 조건", "title": "예산은 얼마까지 생각하세요?", "options": [{"value": 30000, "label": "3만원 이하", "emoji": "💵"}, {"value": 50000, "label": "5만원 이하", "emoji": "💴"}, {"value": 70000, "label": "7만원 이하", "emoji": "💶"}, {"value": 100000, "label": "10만원 이하", "emoji": "💷"}, {"value": 150000, "label": "상관없어요", "emoji": "💎"}]}]$j$::jsonb) with ordinality t(x,o)
on conflict (id) do update set group_name=excluded.group_name, title=excluded.title, sort_order=excluded.sort_order;
insert into quiz_options (question_id,value,label,emoji,sort_order)
select q->>'id', x->>'value', x->>'label', coalesce(x->>'emoji',''), (o-1)
from jsonb_array_elements($j$[{"id": "hunger", "group": "고객 상태", "title": "지금 얼마나 배고프세요?", "options": [{"value": "출출해요", "label": "조금 출출해요", "emoji": "🙂"}, {"value": "적당해요", "label": "적당해요", "emoji": "😋"}, {"value": "매우 배고파요", "label": "매우 배고파요", "emoji": "🤤"}]}, {"id": "stress", "group": "고객 상태", "title": "오늘 스트레스 지수는 어느 정도예요?", "options": [{"value": "낮음", "label": "낮아요", "emoji": "😊"}, {"value": "보통", "label": "보통이에요", "emoji": "😐"}, {"value": "높음", "label": "높아요", "emoji": "😤"}]}, {"id": "people", "group": "방문 인원", "title": "함께 오신 분은 몇 명인가요?", "options": [{"value": 1, "label": "1명", "emoji": "🧑"}, {"value": 2, "label": "2명", "emoji": "👫"}, {"value": 3, "label": "3명", "emoji": "👨‍👩‍👦"}, {"value": 4, "label": "4명", "emoji": "👨‍👩‍👧‍👦"}, {"value": 5, "label": "5명 이상", "emoji": "🧑‍🤝‍🧑"}]}, {"id": "gender", "group": "방문 인원", "title": "일행의 성별은 어떻게 되나요?", "options": [{"value": "남자만", "label": "남자끼리", "emoji": "👨"}, {"value": "여자만", "label": "여자끼리", "emoji": "👩"}, {"value": "혼성", "label": "남녀 함께", "emoji": "👫"}]}, {"id": "kind", "group": "음식 취향", "title": "어떤 종류가 끌리세요?", "options": [{"value": "fried", "label": "튀김·치킨", "emoji": "🍗"}, {"value": "anju", "label": "안주류", "emoji": "🍢"}, {"value": "soup", "label": "탕·국물", "emoji": "🍲"}, {"value": "seafood", "label": "해산물", "emoji": "🦑"}, {"value": "rice_noodle", "label": "밥·면", "emoji": "🍜"}, {"value": "any", "label": "상관없어요", "emoji": "🍽️"}]}, {"id": "spicy", "group": "음식 취향", "title": "맵기는 어느 정도가 좋으세요?", "options": [{"value": "맵지 않게", "label": "맵지 않게", "emoji": "🥛"}, {"value": "상관없어요", "label": "보통이면 좋아요", "emoji": "🌶️"}, {"value": "매콤하게", "label": "매콤하게!", "emoji": "🔥"}]}, {"id": "intent", "group": "방문 상황", "title": "오늘 방문 목적은 무엇인가요?", "options": [{"value": "모임", "label": "친구·모임", "emoji": "🍻"}, {"value": "회식", "label": "회식", "emoji": "🥂"}, {"value": "데이트", "label": "데이트", "emoji": "💕"}, {"value": "가볍게", "label": "가볍게 한잔", "emoji": "🍺"}, {"value": "스트레스", "label": "스트레스 풀러", "emoji": "💥"}]}, {"id": "budget", "group": "소비 조건", "title": "예산은 얼마까지 생각하세요?", "options": [{"value": 30000, "label": "3만원 이하", "emoji": "💵"}, {"value": 50000, "label": "5만원 이하", "emoji": "💴"}, {"value": 70000, "label": "7만원 이하", "emoji": "💶"}, {"value": 100000, "label": "10만원 이하", "emoji": "💷"}, {"value": 150000, "label": "상관없어요", "emoji": "💎"}]}]$j$::jsonb) q, jsonb_array_elements(q->'options') with ordinality t(x,o)
on conflict (question_id,value) do update set label=excluded.label, emoji=excluded.emoji, sort_order=excluded.sort_order;

delete from roulette_prizes;
insert into roulette_prizes (label,short_text,emoji,color,kind,percent,menu_id,weight,sort_order)
select x->>'label', x->>'short', coalesce(x->>'emoji','🎁'), x->>'color', x->>'kind', (x->>'percent')::int, x->>'item_id', coalesce((x->>'weight')::numeric,1), (o-1)
from jsonb_array_elements($j$[{"label": "모든 메뉴<br><b>5% 할인</b>", "short": "전 메뉴 5% 할인", "emoji": "🎟️", "color": "#f0556b", "kind": "discount", "percent": 5}, {"label": "계란말이<br><b>서비스</b>", "short": "계란말이 서비스", "emoji": "🥚", "color": "#ff9f1a", "kind": "free", "item_id": "a4"}, {"label": "음료<br><b>서비스</b>", "short": "콜라 서비스", "emoji": "🥤", "color": "#f5c518", "kind": "free", "item_id": "d1"}, {"label": "라면<br><b>서비스</b>", "short": "라면 서비스", "emoji": "🍜", "color": "#4cc764", "kind": "free", "item_id": "d7"}, {"label": "짜장라면<br><b>서비스</b>", "short": "짜장라면 서비스", "emoji": "🍝", "color": "#3ea0f5", "kind": "free", "item_id": "d8"}]$j$::jsonb) with ordinality t(x,o);

insert into recommendation_rules (key,value) select k, v from jsonb_each($j${"discount_percent": 10, "pairings": [["classic", "바삭한 치킨 한 상", ["c1", "c6"], "바삭한 통닭에 고소한 치즈 감자튀김을 곁들여 함께 나눠 먹기 좋아요."], ["garlic", "달콤짭짤 마늘치킨", ["c2", "c7"], "달콤짭짤한 마늘치킨과 부드러운 크림치즈볼로 맛과 식감을 다르게 즐길 수 있어요."], ["light", "가볍게 즐기는 먹태", ["a1", "a4"], "담백하고 쫄깃한 먹태에 부드러운 계란말이를 더해 식감을 균형 있게 구성했어요."], ["spicy", "매콤한 골뱅이 한 상", ["a2", "a4"], "새콤매콤한 골뱅이 소면에 부드러운 계란말이를 곁들여 매운맛을 쉬어 갈 수 있어요."], ["fire", "불향 가득 닭발 조합", ["a3", "d5"], "불향 나는 매콤한 닭발에 고소한 주먹밥을 더해 든든하게 즐길 수 있어요."], ["soup", "뜨끈한 국물 한 상", ["s2", "a8"], "시원한 어묵탕과 바삭한 해물파전으로 국물과 안주를 함께 즐길 수 있어요."], ["seafood", "얼큰한 해물 조합", ["s1", "c4"], "얼큰한 짬뽕탕에 바삭한 오징어 튀김을 곁들여 국물과 튀김의 식감을 살렸어요."], ["value", "알뜰하게 나누는 한 상", ["c3", "c7"], "쫄깃한 닭똥집과 고소한 치즈볼로 부담 적은 가격에 두 가지 안주를 즐길 수 있어요."], ["comfort", "고소하고 부드러운 조합", ["a4", "c7"], "부드러운 계란말이와 고소한 크림치즈볼로 맵지 않은 안주를 구성했어요."], ["dry", "건어물과 소시지 조합", ["a10", "a5"], "오래 나눠 먹기 좋은 건어물에 따뜻한 모둠 소시지를 곁들였어요."], ["ramen", "해장 라면 한 상", ["a4", "d7"], "부드러운 계란말이와 얼큰하게 끓인 라면으로 속을 든든하게 채울 수 있어요."], ["dooroochi", "두루치기 밥 한 상", ["s5", "d3"], "푹 익은 김치 두루치기에 공깃밥을 더해 든든한 한 끼 안주로 좋아요."], ["mussel", "시원한 홍합탕 조합", ["s4", "c4"], "시원한 홍합탕에 바삭한 오징어 튀김을 곁들여 국물과 튀김을 함께 즐길 수 있어요."]], "drinks": {"맥주": "b1", "소주": "j1", "음료": "d2", "없이": null}, "pair_meta": {"classic": {"kinds": ["fried"], "occasions": ["모임", "회식"], "mood": "hearty"}, "garlic": {"kinds": ["fried"], "occasions": ["데이트", "모임"], "mood": null}, "light": {"kinds": ["anju"], "occasions": ["가볍게", "데이트"], "mood": "light"}, "spicy": {"kinds": ["anju"], "occasions": ["스트레스", "회식"], "mood": "hearty"}, "fire": {"kinds": ["anju"], "occasions": ["스트레스"], "mood": null}, "soup": {"kinds": ["soup"], "occasions": ["모임", "회식"], "mood": "hearty"}, "seafood": {"kinds": ["seafood", "soup"], "occasions": ["스트레스", "회식"], "mood": "hearty"}, "value": {"kinds": ["fried"], "occasions": ["가볍게", "모임"], "mood": null}, "comfort": {"kinds": ["anju"], "occasions": ["가볍게", "데이트"], "mood": "light"}, "dry": {"kinds": ["anju"], "occasions": ["가볍게", "모임"], "mood": "light"}, "ramen": {"kinds": ["rice_noodle"], "occasions": ["가볍게"], "mood": "light"}, "dooroochi": {"kinds": ["rice_noodle"], "occasions": ["회식"], "mood": "hearty"}, "mussel": {"kinds": ["seafood", "soup"], "occasions": ["데이트", "모임"], "mood": null}}, "hot_themed": ["dooroochi", "fire", "seafood", "spicy"], "kind_label": {"fried": "튀김·치킨", "anju": "안주", "soup": "탕·국물", "seafood": "해산물", "rice_noodle": "밥·면"}, "intent_label": {"모임": "친구·모임", "회식": "회식", "데이트": "데이트", "가볍게": "가볍게 한잔", "스트레스": "스트레스 푸는 자리"}}$j$::jsonb) e(k,v)
on conflict (key) do update set value=excluded.value, updated_at=now();
insert into staff_call_items (label,sort_order)
select x, (o-1) from jsonb_array_elements_text($j$["💧 물", "🥄 수저·젓가락", "🍽️ 앞접시", "🧻 휴지·물티슈", "🧊 얼음", "🔥 가스불 점검", "💳 계산 요청", "🙋 기타 문의"]$j$::jsonb) with ordinality t(x,o)
on conflict (label) do update set sort_order=excluded.sort_order;
commit;
